import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic(); // ключ из ANTHROPIC_API_KEY
const messages: Anthropic.MessageParam[] = []; // вся «память» диалога живёт здесь

async function ask(question: string) {
  messages.push({ role: "user", content: question });
  const res = await client.messages.create({
    model: "claude-sonnet-5",
    max_tokens: 1024,
    system: "You are a concise assistant.",
    messages, // каждый раз уходит ВЕСЬ массив
  });
  messages.push({ role: "assistant", content: res.content });
  console.log(res.usage.input_tokens); // растёт с каждым ходом
  return res;
}

async function main() {
  await ask("My name is Anton.");
  await ask("What is my name?"); // ответит «Anton» только потому, что первый ход лежит в messages
}

main();

// Иллюстративные числа: system prompt 1 000 токенов,
// каждый ход добавляет вопрос (200) и ответ (300)
const SYSTEM = 1000, USER = 200, ASSISTANT = 300;

function simulate(turns) {
  let history = 0, billedInput = 0, lastInput = 0;
  for (let k = 1; k <= turns; k++) {
    lastInput = SYSTEM + history + USER; // всё прошлое + новый вопрос
    billedInput += lastInput;
    history += USER + ASSISTANT;         // новая пара уходит в историю
  }
  return { turns, lastInput, billedInput };
}
for (const n of [1, 10, 50, 100]) console.log(simulate(n));

// { turns: 1, lastInput: 1200, billedInput: 1200 }
// { turns: 10, lastInput: 5700, billedInput: 34500 }
// { turns: 50, lastInput: 25700, billedInput: 672500 }
// { turns: 100, lastInput: 50700, billedInput: 2595000 }

// Иллюстративная агентная петля: каждый шаг читает страницу в 3 500 токенов
const PAGE = 3500, STEPS = 6;
let context = 0, sent = 0;
for (let step = 1; step <= STEPS; step++) {
  context += PAGE; // новый tool_result попадает в историю
  sent += context; // следующий запрос пересылает её целиком
}
console.log({ unique: PAGE * STEPS, sent, ratio: sent / (PAGE * STEPS) });
// { unique: 21000, sent: 73500, ratio: 3.5 }

function slidingWindow(messages, keepPairs) {
  // последние N пар user+assistant; окно обязано начинаться с user
  let start = Math.max(0, messages.length - keepPairs * 2);
  while (start < messages.length && messages[start].role !== "user") start++;
  return messages.slice(start);
}

const msgs = [
  { role: "user", content: "My name is Anton." },
  { role: "assistant", content: "Hi Anton!" },
  { role: "user", content: "I use Next.js." },
  { role: "assistant", content: "Nice." },
  { role: "user", content: "What is my name?" },
];
console.log(slidingWindow(msgs, 2).map((m) => m.content));
// [ 'I use Next.js.', 'Nice.', 'What is my name?' ]  ← имя молча потеряно

